"""Completed probability-first follow-up: exact paired transitions and trace audit."""
from pathlib import Path
import collections,gzip,hashlib,html,json,re
R=Path(__file__).resolve().parent
with gzip.open(R.parent/'FINAL_ANALYSIS_SNAPSHOT.json.gz','rt') as f:data=json.load(f)
rows=data['rows'];assert len(rows)==35919
J=['qwen','gemma','mistral','olmo','glm','qwen122']
NAMES=dict(qwen='Qwen 27B',gemma='Gemma',mistral='Mistral',olmo='OLMo',glm='GLM',qwen122='Qwen 122B')
assert len({(x['judge'],x['backbone'],x['sample_id']) for x in rows})==len(rows)
def summarize(rs):
 valid=[x for x in rs if type(x['reason_probability']) is int and 0<=x['reason_probability']<=100]
 h=[x for x in valid if x['flip_type']=='helped'];bad=[x for x in valid if x['flip_type']=='harmed']
 for x in valid:
  assert (x['control_probability']>=50)!=(x['nn_probability']>=50)
  assert ((x['nn_probability']>=50)==x['true_label'])==(x['flip_type']=='helped')
 fix=sum((x['reason_probability']>=50)==x['true_label'] for x in bad)
 undo=sum((x['reason_probability']>=50)!=x['true_label'] for x in h)
 old=len(h);new=sum((x['reason_probability']>=50)==x['true_label'] for x in valid)
 assert new-old==fix-undo
 w=lambda x:1/x['inclusion_probability']
 wn=sum(w(x) for x in valid)
 weighted=sum(w(x)*(int((x['reason_probability']>=50)==x['true_label'])-int((x['nn_probability']>=50)==x['true_label'])) for x in valid)
 references=sum(bool(re.search(r'\b(?:reference example|nearest neighbou?r|neighbou?r|probe)\b',x['reasoning'],re.I)) for x in valid)
 explicit=0
 for x in valid:
  nums=[int(s.strip()) for s in x['reasoning'].splitlines() if re.fullmatch(r'(?:0|[1-9][0-9]?|100)',s.strip())]
  explicit+=any((n>=50)!=(x['reason_probability']>=50) for n in nums)
 return dict(planned=len(rs),valid=len(valid),missing_or_invalid=len(rs)-len(valid),unique_text_ids=len({x['sample_id'] for x in valid}),original_helpful=len(h),original_harmful=len(bad),corrected_harmful=fix,undone_helpful=undo,retained_helpful=len(h)-undo,retained_harmful=len(bad)-fix,changed=fix+undo,unchanged=len(valid)-fix-undo,corrective_share=fix/(fix+undo) if fix+undo else None,repair_rate=fix/len(bad) if bad else None,undo_rate=undo/len(h) if h else None,net_correct=fix-undo,original_nn_accuracy=old/len(valid),reason_after_accuracy=new/len(valid),delta_accuracy_pp=100*(new-old)/len(valid),weighted_conditional_delta_accuracy_pp=100*weighted/wn,capped=sum(x['finish_reason']=='length' for x in valid),explicit_reference_or_probe_mentions=references,later_standalone_number_disagrees=explicit)
summary=[dict(judge=j,**summarize([x for x in rows if x['judge']==j])) for j in J]
datasets=[dict(judge=j,dataset=d,**summarize([x for x in rows if x['judge']==j and x['dataset']==d])) for j in J for d in sorted({x['dataset'] for x in rows})]
backbones=[dict(judge=j,backbone=b,**summarize([x for x in rows if x['judge']==j and x['backbone']==b])) for j in J for b in sorted({x['backbone'] for x in rows})]
assert sum(s['valid'] for s in summary)==35917 and sum(s['capped'] for s in summary)==516
total=summarize(rows);assert total['changed']==35917-28220
result=dict(summary=summary,datasets=datasets,backbones=backbones,total=total,method='Unweighted exact paired counts on each judge own outcome-selected original fixed50 test-flip subset. Same threshold50 for all comparisons. Two missing prior attempts excluded from valid denominators. These are conditional diagnostic results, not full-test F1 or independent trials. Weighted conditional sensitivity retains original inverse inclusion probabilities; it still describes selected flips only. No threshold tuning or inference performed.',qualitative_method='24 deterministic hash-selected traces: one per judge by four outcome states, plus12 targeted explicit reference/probe mentions split equally originally helpful/harmful and retaining NN prediction. Targeted lexical selection may retrieve source-evidence references rather than NN references. Manual notes are illustrative, not estimates of mechanism prevalence. Full original target/neighbour context is retained.',source_sha256=hashlib.sha256((R.parent/'FINAL_ANALYSIS_SNAPSHOT.json.gz').read_bytes()).hexdigest(),script_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest())
(R/'summary.json').write_text(json.dumps(result,indent=2)+'\n')
with gzip.open(R/'EXAMPLE_CONTEXTS.json.gz','rt') as f:contexts={(x['backbone'],x['sample_id']):x for x in json.load(f)}
examples=json.loads((R/'qualitative_sample.json').read_text())
notes={
0:'Task-only justification; no explicit use of the neighbour.',1:'Explicit contradiction: first probability10 says negative; the explanation calls the target harmful and cites a harmful neighbour. Correct score does not make the explanation coherent.',2:'Task interpretation differs from gold: treats inaccurate fictional parody as harmless. No explicit NN mechanism.',3:'Interprets a fantasy narrative as facilitating fraud; disagrees with gold. No explicit NN comparison.',
4:'Task-only threshold judgment about mild insult.',5:'Checks source evidence directly; no explicit NN use.',6:'Calls a disability joke non-toxic; gold-label disagreement.',7:'Treats a sarcastic insult as harmful assistance; gold-label disagreement.',
8:'Explicitly discounts the reference example as unrelated, then checks evidence. Consistent with selective rather than blind neighbour use.',9:'Direct harmful-content recognition; no explicit neighbour comparison.',10:'Calls the target a neutral restatement; disagreement with benchmark gold.',11:'Infers criminal context from the target; no explicit neighbour comparison.',
12:'Task-only observation-versus-toxicity distinction.',13:'Acknowledges ambiguity and chooses50, which is positive in this protocol.',14:'Clear score–explanation contradiction: first0 says no hallucination, while explanation identifies false information against the evidence.',15:'Interprets a routine medical procedure as low-stakes despite high-stakes gold; a disagreement about task scope.',
16:'Checks evidence and explains the factual contradiction directly.',17:'Helpful labelled analogy: near-paraphrase neighbour is safe, supporting the target safe answer. Verified against the actual neighbour label.',18:'Clear score–explanation contradiction: first50 is positive/hallucinated, yet explanation says the answer is supported by evidence. Also discounts an unrelated neighbour.',19:'Cites shared fictional framing to support a harmful interpretation, contrary to the target gold label.',
20:'Separates casual text from the surrounding mental-health framing; no explicit NN use.',21:'Helpful contrast: explains why a drug-use neighbour is more concretely harmful than the target philosophical request. Corrects the earlier harmful analogy.',22:'Treats platform-rule evasion as unsafe; benchmark-label disagreement.',23:'PII request judged unsafe although benchmark gold is safe; no explicit NN comparison.',
24:'Explicit label/probe distinction: says the harmless training label is more appropriate than the probe harmful prediction. Supports label-based calibration, but does not isolate a benefit of showing the probe prediction.',25:'Overgeneralizes from a reference to fictional medical data; retained harmful flip against gold.',26:'Helpful analogy between academic framing used for misinformation requests, relative to dataset gold.',27:'Potential misleading analogy: projects sexual-violence/incest content onto a generic taboo-society target by analogy with a more specific harmful neighbour.',
28:'Lexical false positive for NN mechanism: Reference[2] is source evidence, not necessarily the retrieved training example. Do not count as NN use.',29:'Interprets wording through a toxic-reference analogy, but target gold is non-toxic.',30:'Helpful contrast: explicitly distinguishes relationship-story content from a harmful welfare-recipient neighbour.',31:'Recognizes benign alien-abduction fiction but invokes harmful-request structure and chooses50; the cutoff makes this a false positive.',
32:'Neighbour reinforces a benign/low-stakes interpretation.',33:'Misleading low-stakes analogy: minor sprain example supports downgrading a central venous catheter procedure, contrary to gold.',34:'Helpful contrast: separates a gender/political discussion from a neighbour explicitly requesting murder information.',35:'Uses a low-stakes reference to discount financial/real-estate content; disagrees with target high-stakes gold.'}
for i,e in enumerate(examples):e['audit_note']=notes[i];e['messages']=contexts[e['backbone'],e['sample_id']]['messages']
(R/'audited_examples.json').write_text(json.dumps(examples,indent=2,ensure_ascii=False)+'\n')
esc=lambda x:html.escape(str(x))
def table(rs,key):
 out='<table><thead><tr><th>'+key.title()+'</th><th>Valid n</th><th>Corrected / harmful</th><th>Undone / helpful</th><th>Corrective share</th><th>Net correct</th><th>Accuracy Δ pp</th></tr></thead><tbody>'
 for s in rs:
  name=NAMES.get(s[key],s[key]);share='—' if s['corrective_share'] is None else f"{s['corrective_share']*100:.1f}%"
  out+=f"<tr><td>{esc(name)}</td><td>{s['valid']:,}</td><td>{s['corrected_harmful']:,} / {s['original_harmful']:,}</td><td>{s['undone_helpful']:,} / {s['original_helpful']:,}</td><td>{share}</td><td>{s['net_correct']:+,}</td><td>{s['delta_accuracy_pp']:+.2f}</td></tr>"
 return out+'</tbody></table>'
page='''<!doctype html><html><meta charset="utf-8"><title>Completed NN explanation-after analysis</title><style>body{font:16px/1.55 system-ui;color:#20303d;max-width:1220px;margin:35px auto;padding:0 24px}h1{font-size:30px}h2{margin-top:35px}table{border-collapse:collapse;width:100%;font-size:15px}td,th{padding:10px;border-bottom:1px solid #dce3e9;text-align:left}th{background:#eef3f7}details{border:1px solid #dce3e9;border-radius:8px;padding:15px;margin:16px 0}summary{cursor:pointer;font-weight:600}pre{white-space:pre-wrap;font:inherit;overflow-wrap:anywhere}blockquote{border-left:4px solid #5d88a0;padding-left:16px;margin-left:0}.note{padding:18px;background:#eef3f7;border-radius:8px}small{color:#617080}code{overflow-wrap:anywhere}</style><h1>Does requesting an explanation correct or undo NN flips?</h1><p>Completed17 October2026. Six local judges; five backbones; ten datasets. Original probability-only control and1-NN decisions disagreed at50. We asked for a new probability first, then a VERY brief explanation. All binary changes therefore return to the original control classification.</p><div class="note"><b>Mixed by judge.</b> Qwen27B, Mistral and Qwen122B make more corrections than regressions. Gemma is near balanced. GLM and especially OLMo lose more originally helpful flips. Across all observed decisions there are3,384 corrections and4,313 regressions; this pooled count is dominated by unequal judge subset sizes and must not be interpreted as full-test performance.</div>'''
page+='<h2>All judges</h2>'+table(summary,'judge')
page+='<details><summary>Weighting sensitivity on the selected flip subset</summary><table><tr><th>Judge</th><th>Raw accuracy Δ pp</th><th>Design-weighted conditional Δ pp</th></tr>'+''.join(f"<tr><td>{NAMES[z['judge']]}</td><td>{z['delta_accuracy_pp']:+.2f}</td><td>{z['weighted_conditional_delta_accuracy_pp']:+.2f}</td></tr>" for z in summary)+'</table><p>This sensitivity applies inverse original selection probabilities within each judge’s selected flips. It is still conditional on being a flip and does not estimate full-test performance. The modest positive raw Qwen changes reverse under weighting; Mistral stays positive. Dataset and backbone weights here are induced by their weighted flip populations, not equal-cell macro averaging.</p></details>'
page+='<p>35,919 planned cases;35,917 valid first probabilities; two previous interrupted Qwen attempts remain missing.516 explanations reached the256-token cap, but their first probabilities are retained. Counts are raw, not independent observations: texts can recur across backbones, and each judge has its own selected cases. Accuracy changes describe only these original flips, not full-test F1. Settings stayed greedy, but prompt and batching changes prevent attributing every difference uniquely to reasoning.</p>'
page+='''<h2>What the explanations show</h2><ul><li><b>Labelled analogy/calibration:</b> judges sometimes explicitly use the neighbour to interpret what counts as positive or negative in this task.</li><li><b>Contrast:</b> judges sometimes distinguish a superficially similar target from a neighbour with a more clearly harmful feature; this can support the opposite answer to the neighbour label.</li><li><b>Misleading analogy:</b> fictional framing, sensitive subject matter or routine medical outcomes can induce inappropriate transfers from the neighbour.</li><li><b>Text is not guaranteed to match the scored answer:</b> some explanations explicitly support the opposite class to the number just produced. Other explanations only discuss the target and never mention the neighbour. These are expressed rationales, not proof of an internal causal mechanism.</li></ul><p>The36 audited traces below are illustrative:24 deterministic cases balanced by judge and transition, plus12 deliberately selected reference/probe mentions. This is not a prevalence estimate or blind human coding of all35,917 traces. The phrase “Reference” can refer to source documents instead of the neighbour; example29 illustrates this lexical ambiguity.</p><h2>Dataset and backbone breakdowns</h2>'''
for j in J:
 page+='<details><summary>'+NAMES[j]+' — heterogeneity</summary><h3>Datasets</h3>'+table([x for x in datasets if x['judge']==j],'dataset')+'<h3>Backbones</h3>'+table([x for x in backbones if x['judge']==j],'backbone')+'</details>'
page+='<p>OLMo: FAVA −474 and HaluEval −400 account for874 of its1,004 net lost correct answers. GLM: HaluEval −199 is the largest negative contributor; its total is −229. These figures locate the failures, rather than establishing their cause.</p><h2>Exact traces and original target/neighbour context</h2>'
for i,e in enumerate(examples):
 page+=f"<details id='example-{i+1}'><summary>{i+1}. {NAMES[e['judge']]} / {esc(e['dataset'])} / {esc(e['state'])}</summary><p>Control {e['control_probability']} → original NN {e['nn_probability']} → explanation-prompt probability {e['reason_probability']}; target gold {e['true_label']}; {esc(e['finish_reason'])}.</p><p><b>Audit:</b> {esc(e['audit_note'])}</p><blockquote>{esc(e['reasoning'])}</blockquote><details><summary>Exact task and reference context</summary><pre>{esc(e['messages'][0]['content'])}</pre><pre>{esc(e['messages'][1]['content'])}</pre></details><small>{esc(e['backbone'])} · {esc(e['sample_id'])}</small></details>"
page+='</html>'
(R/'report.html').write_text(page)
print(json.dumps(dict(summary=summary,total=total),indent=2))
